#[test]
fn test_find_count_only_prints_total() {
    let dir = setup_workspace();

    write(dir.path().join("alpha.md"), "# Alpha\n\nContent.").unwrap();
    write(dir.path().join("beta.md"), "# Beta\n\nContent.").unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout, "2\n");
}

#[test]
fn test_find_count_honors_filters() {
    let dir = setup_workspace();

    write(
        dir.path().join("root.md"),
        indoc! {"
            ---
            kind: note
            ---
            # Root

            [child](child)
        "},
    )
    .unwrap();

    write(
        dir.path().join("child.md"),
        indoc! {"
            ---
            kind: note
            ---
            # Child

            Child content.
        "},
    )
    .unwrap();

    write(
        dir.path().join("other.md"),
        indoc! {"
            ---
            kind: task
            ---
            # Other

            [child](child)
        "},
    )
    .unwrap();

    let (stdout, stderr, success) =
        run_iwe(dir.path(), &["--count", "--roots", "--refs-to", "child", "--meta", "kind=note"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout, "1\n");
}

#[test]
fn test_find_count_ignores_output_format() {
    let dir = setup_workspace();

    write(dir.path().join("alpha.md"), "# Alpha\n\nContent.").unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--count", "-f", "json"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout, "1\n");
}
